def add_keys(loc, file, hash)
  f = "config/locales/#{loc}/#{file}.yml"
  data = File.exist?(f) ? (YAML.load_file(f) || {}) : {}
  root = data[loc] || {}
  deep = ->(a, b) { a.merge(b) { |_, x, y| x.is_a?(Hash) && y.is_a?(Hash) ? deep.(x, y) : y } }
